    unwritten       UBIGINT,   -- checked PROC records the WAL refused (an I/O failure; the run is already INVALID)
    kthreads        UBIGINT,   -- entries that are kernel threads (no argv, no executable)
    exiting         UBIGINT,   -- entries already exiting, without an mm (no argv, no executable): not read failures
    argv_failed     UBIGINT,   -- entries whose argv could not be read (bpf_copy_from_user_task failed): P15_F_READ_FAILED
    path_unlocked   UBIGINT,   -- entries whose executable path was not read because the task's mmap lock was busy or the iterator cou...
    path_not_found  UBIGINT,   -- entries whose mapping at mm->start_code is not mm->exe_file, so the path is not read: P15_F_READ_FAI...
    path_failed     UBIGINT,   -- entries where bpf_d_path failed for another reason than length: P15_F_READ_FAILED
    truncated       UBIGINT,   -- fields cut: an argv longer than its maximum, or a path longer than its maximum (a record with both c...
    fd_duration_ns  UBIGINT,   -- CLOCK_BOOTTIME of the FD pass, from creating its iterator to its end of output; 0 without the pass
    fd_files        UBIGINT,   -- descriptors the task_file iterator showed the program (thread-group fd tables; threads sharing the l...
    fd_no_inode     UBIGINT,   -- descriptors whose file has no inode: not recorded (never expected)
    fd_emitted      UBIGINT,   -- FD records the program wrote to the iterator's output
    fd_write_failed UBIGINT,   -- bpf_seq_write refused an FD record: that descriptor is missing (run INVALID)
    fd_entries      UBIGINT,   -- FD records that passed p15_rec_check and went into the WAL
    fd_invalid      UBIGINT,   -- FD output that failed p15_rec_check or did not frame: counted, never written (run INVALID)
    fd_unwritten    UBIGINT,   -- checked FD records the WAL refused
    fd_known        UBIGINT,   -- emitted FD rows whose open file capture had already registered (an OPEN, or an earlier snapshot): th...
    fd_registered   UBIGINT,   -- emitted FD rows that registered their open file now (opened before capture began)
    fd_map_full     UBIGINT,   -- emitted FD rows written with a fresh, unregistered open-file id because the open-file map was full
    fd_path_error   UBIGINT,   -- emitted FD rows whose bpf_d_path failed for a reason other than length (PATH_ERROR)
    fd_truncated    UBIGINT,   -- emitted FD rows whose path did not fit (the dentry name, TRUNCATED)
    snap_id         UINTEGER,  -- as in PROC
    error           INTEGER,   -- 0, or the negative errno that ended reading the iterator early (then the snapshot is incomplete and ...
    fd_error        INTEGER,   -- 0, or the negative errno that ended the FD pass early (snapshot incomplete, run INVALID)
    kind            USMALLINT, -- as in PROC
    fd_pass         USMALLINT  -- 1 if the FD pass ran (file identity loaded), 0 if not (--no-files): then every fd_* field is 0
);

