CREATE TABLE raw_file_stats (
    ring                        UTINYINT,  -- the ring the record came from: 0 spine, 1 bulk, 2 daemon
    seq                         UBIGINT,   -- its sequence number in that ring; (ring, seq) names a record of the run
    version                     USMALLINT, -- layout version of that type
    flags                       USMALLINT, -- P15_F_* flags
    ts_ns                       UBIGINT,   -- event time, CLOCK_BOOTTIME ns (bpf_ktime_get_boot_ns)
    tgid                        UINTEGER,  -- thread-group id, init pid namespace (ADR-0009)
    tid                         UINTEGER,  -- thread id, init pid namespace
    start_ns                    UBIGINT,   -- group_leader->start_boottime: with tgid and the segment's boot_id, the process identity (ADR-0009)
    fentry_run                  UBIGINT,   -- the path fentry ran; cumulative
    fentry_no_inode             UBIGINT,   -- ... for a file without an inode (never expected: counted, nothing written); cumulative
    open_emitted                UBIGINT,   -- OPEN records the fentry submitted; cumulative
    open_lost                   UBIGINT,   -- ... lost to a full bulk ring (run DEGRADED); cumulative
    open_full_size              UBIGINT,   -- ... written full size: no scratch slot was free (rule 6); cumulative
    open_truncated              UBIGINT,   -- ... whose path did not fit (dentry name, TRUNCATED); cumulative
    open_path_error             UBIGINT,   -- ... whose bpf_d_path failed otherwise (PATH_ERROR); cumulative
    backing_emitted             UBIGINT,   -- BACKING records submitted; cumulative
    backing_lost                UBIGINT,   -- BACKING records lost to a full bulk ring (run DEGRADED); cumulative
    backing_user_unread         UBIGINT,   -- BACKING without the overlay inode (user_obj 0, READ_FAILED); cumulative
    session_entry               UBIGINT,   -- the kprobe.session ran at entry; cumulative
    session_no_inode            UBIGINT,   -- ... for a file without an inode: no return run; cumulative
    session_return              UBIGINT,   -- the session's return run; cumulative
    session_common              UBIGINT,   -- ... with the OPEN written and verdict 0: nothing to write; cumulative
    missing_emitted             UBIGINT,   -- OPEN with PATH_MISSING (the fentry did not run); cumulative
    missing_lost                UBIGINT,   -- PATH_MISSING OPEN records lost to a full bulk ring (run DEGRADED); cumulative
    verdict_emitted             UBIGINT,   -- OPEN_VERDICT; cumulative
    verdict_lost                UBIGINT,   -- OPEN_VERDICT records lost to a full bulk ring (run DEGRADED); cumulative
    session_no_cookie           UBIGINT,   -- return run with an empty cookie (never expected); cumulative
    session_no_entry            UBIGINT,   -- return run without an open-file entry (its map was full); cumulative
    free_run                    UBIGINT,   -- security_file_free ran (every struct file of the system); cumulative
    close_emitted               UBIGINT,   -- CLOSE records submitted; cumulative
    close_lost                  UBIGINT,   -- CLOSE records lost to a full bulk ring (run DEGRADED); cumulative
    free_unregistered           UBIGINT,   -- a free of a file capture never registered (decision 19.5); cumulative
    inode_free_run              UBIGINT,   -- security_inode_free ran; cumulative
    inode_free_hit              UBIGINT,   -- ... and deleted an object entry; cumulative
    file_map_full               UBIGINT,   -- no open-file entry: the event is written with a fresh, unregistered id; cumulative
    obj_map_full                UBIGINT,   -- no object entry: the facts go inline, with a fresh id; cumulative
    file_stale                  UBIGINT,   -- an entry whose stored inode differs from the live file's: replaced (rule 9); cumulative
    obj_stale                   UBIGINT,   -- an entry whose dev/ino/gen differ from the live inode's: replaced; cumulative
    file_race                   UBIGINT,   -- another program inserted the entry between lookup and insert; cumulative
    obj_race                    UBIGINT,   -- another program inserted the object entry between lookup and insert; cumulative
    facts_dup                   UBIGINT,   -- a second record carried an object's facts (decision 19.7: twice, never zero); cumulative
    subvol_unknown              UBIGINT,   -- facts of a btrfs object read without btrfs BTF (oflags SUBVOL_UNKNOWN); cumulative
    kthread_open                UBIGINT,   -- OPEN records written in a kernel thread (KTHREAD); cumulative
    walked                      UBIGINT,   -- the session return's OPENs with the walked path (PATH_WALKED); with walk_unnamed, missing_emitted; c...
    walk_raced                  UBIGINT,   -- ... of which PATH_RACED: the tree moved during both tries; cumulative
    walk_truncated              UBIGINT,   -- ... of which TRUNCATED: a bound of the walk cut the path; cumulative
    walk_unnamed                UBIGINT,   -- the session return's OPENs without a path (PATH_MISSING): an unknown d_dname, no fs, no scratch; cum...
    ret_backing                 UBIGINT,   -- session returns, with the fentry skipped, for an FMODE_BACKING file: BACKING written or lost; cumula...
    ret_backing_emitted         UBIGINT,   -- BACKING records the session return submitted; cumulative
    ret_backing_lost            UBIGINT,   -- ... lost to a full bulk ring (run DEGRADED); cumulative
    ret_backing_verdict_emitted UBIGINT,   -- OPEN_VERDICT records after such a BACKING (a denial); cumulative
    ret_backing_verdict_lost    UBIGINT,   -- ... lost to a full bulk ring (run DEGRADED); cumulative
    files_live                  UBIGINT,   -- open-file entries now (the FILES_LIVE gauge)
    objs_live                   UBIGINT,   -- object entries now (the OBJS_LIVE gauge)
    files_live_max              UBIGINT,   -- the most open-file entries the drain saw at a poll, since the run's start
    objs_live_max               UBIGINT,   -- the most object entries the drain saw at a poll, since the run's start
    file_drained                UBIGINT,   -- file-identity records the drain copied into a batch, cumulative
    file_invalid                UBIGINT,   -- file-identity records refused by p15_rec_check, never written (run DEGRADED), cumulative
    fentry_missed               UBIGINT,   -- opens whose path fentry the kernel skipped (its recursion_misses): each has an OPEN with PATH_MISSIN...
    kprobe_missed               UBIGINT,   -- runs the kernel skipped of the session and the two free programs (recursion_misses; run DEGRADED)
    file_map_entries            UINTEGER,  -- the open-file map's size (--file-map-entries)
    obj_map_entries             UINTEGER   -- the object map's size (--obj-map-entries)
);

