    read_emitted         UBIGINT,   -- FLOW records of kind READ submitted; cumulative
    write_emitted        UBIGINT,   -- ... WRITE; cumulative
    send_emitted         UBIGINT,   -- ... SEND; cumulative
    recv_emitted         UBIGINT,   -- ... RECV; cumulative
    flow_lost            UBIGINT,   -- FLOW records lost to a full bulk ring (run DEGRADED); cumulative
    start_unknown        UBIGINT,   -- vfs FLOWs whose entry time was not kept (START_UNKNOWN); a sub-count of the emitted; cumulative
    unregistered         UBIGINT,   -- FLOWs on a file with no entry, facts inline (UNREGISTERED, reason MAP_FULL); a sub-count of the emit...
    file_emitted         UBIGINT,   -- FILE records for a file first seen at a transfer (ADR-0015 rule 5); cumulative
    file_lost            UBIGINT,   -- ... lost to a full bulk ring (run DEGRADED; the open-file entry is removed so the next transfer retr...
    file_map_full        UBIGINT,   -- a pseudo file the files map was too full to register (its FLOW is UNREGISTERED); cumulative
    v_gated              UBIGINT,   -- a vfs entry after the gate shut at the run's end: no slot opened, no return (p15_flow.h); cumulative
    v_no_slot_entry      UBIGINT,   -- a vfs entry whose task slot could not be made: marked in the session's cookie; cumulative
    v_no_slot_return     UBIGINT,   -- ... and its return; the difference is the slot-less calls still open; cumulative
    open_at_end          UBIGINT,   -- vfs calls the end's task iterator found open and claimed: entered in the run, not returned at its co...
    returned_after_count UBIGINT,   -- ... of which these returned before the detach (their FLOW is written); cumulative
    v_release_failed     UBIGINT,   -- a return that could not take its call off its task's count (expected 0); cumulative
    v_entry_while_open   UBIGINT,   -- an entry by a task with a call already open: a nested call, or an earlier return of that task was lo...
    v_claim_race         UBIGINT,   -- tasks whose slot the end's iterator gave up on after its tries (expected 0; reported); cumulative
    flow_drained         UBIGINT,   -- FLOW and FILE records the drain copied into a batch; cumulative
    flow_invalid         UBIGINT,   -- FLOW or FILE records refused by p15_rec_check, never written (run DEGRADED); cumulative
    flow_missed          UBIGINT    -- runs of the flow programs the kernel skipped (their recursion_misses summed; run DEGRADED); cumulati...
);

CREATE TABLE raw_flow (
    ring           UTINYINT,  -- the ring the record came from: 0 spine, 1 bulk, 2 daemon
    seq            UBIGINT,   -- its sequence number in that ring; (ring, seq) names a record of the run
    version        USMALLINT, -- layout version of that type
    flags          USMALLINT, -- P15_F_* flags
    ts_ns          UBIGINT,   -- event time, CLOCK_BOOTTIME ns (bpf_ktime_get_boot_ns)
    tgid           UINTEGER,  -- thread-group id, init pid namespace (ADR-0009)
    tid            UINTEGER,  -- thread id, init pid namespace
    start_ns       UBIGINT,   -- group_leader->start_boottime: with tgid and the segment's boot_id, the process identity (ADR-0009)
    fid            UBIGINT,   -- the open-file id (ADR-0015 rule 1); with UNREGISTERED, a fresh id of this record only
    obj            UBIGINT,   -- the object id of the file's inode
    first_ts       UBIGINT,   -- start of the first event, CLOCK_BOOTTIME ns; with START_UNKNOWN its end; a socket event is an instan...
    last_ts        UBIGINT,   -- end of the last event, CLOCK_BOOTTIME ns
    bytes          UBIGINT,   -- bytes moved, the sum of the events' returns (each at least 1: failed and empty transfers are counted...
    count          UINTEGER,  -- events in the aggregate, at least 1; 1 with reason SINGLE
    fflags         UINTEGER,  -- P15_FF_* (OBJ_NEW, UNREGISTERED, PEEK, VECTORED, START_UNKNOWN)
    kind           USMALLINT, -- P15_FLOW_KIND_*
    reason         USMALLINT, -- P15_FLOW_REASON_*: why it was written
    facts_full     UINTEGER,  -- full length of facts in bytes; P15_LEN_UNKNOWN if cut and not known
    facts_len      USMALLINT, -- bytes of facts present in this record
    facts_ino      UBIGINT,   -- facts: i_ino
    facts_subvol   UBIGINT,   -- facts: btrfs: the subvolume's root id (what statx reports as stx_subvol); 0 elsewhere, and 0 with SU...
    facts_dev      UINTEGER,  -- facts: i_sb->s_dev, kernel encoding (major << 20 | minor)
    facts_gen      UINTEGER,  -- facts: i_generation (random on ext4, xfs v3 and tmpfs; a transaction id on btrfs; 0 on pipes, socket...
    facts_mode     UINTEGER,  -- facts: i_mode: file type and permission bits
    facts_fs_magic UINTEGER,  -- facts: low 32 bits of i_sb->s_magic: ext4 0xEF53, tmpfs 0x01021994, btrfs 0x9123683E, overlayfs 0x79...
    facts_nlink    UINTEGER,  -- facts: i_nlink when the facts were read; 0 = unlinked (a deleted file, a memfd, an O_TMPFILE)
    facts_seen     USMALLINT, -- facts: how capture first saw the object: 1 open, 2 snapshot FD pass, 3 first I/O, 4 mmap, 5 network ...
    facts_oflags   USMALLINT  -- facts: bit 0 SUBVOL_UNKNOWN: a btrfs object (fs_magic 0x9123683E) while btrfs's BTF was absent at lo...
);
